    public function bookingReviews(string $hotel, array $options = []): array
    {
        return $this->postJson('/travel/booking-reviews', [
            'hotel' => $hotel,
            'languages' => $options['languages'] ?? null,
            'max_results' => $options['max_results'] ?? null,
            'since' => $options['since'] ?? null,
            'proxy_country' => $options['proxy_country'] ?? null,
        ]);
    }

    /**
     * Scrape Airbnb stay listings.
     *
     * Searches Airbnb for `location` and returns the stay listings as JSON: `name`, `roomType`,
     * `price` (USD by default) with any original price, `rating` and `reviewCount`, coordinates,
     * `badges` (e.g. Guest favourite), `image` and a clean room `url`. Filter with
     * `checkin`/`checkout`, `adults`, `min_price`/`max_price` and `room_type`, and collect up to
     * `max_results` across pages.
     *
     * @param string $location City to search, e.g. 'Austin, TX' or 'Paris, France'.
     * @param array{checkin?: string, checkout?: string, adults?: int, room_type?: string, min_price?: int, max_price?: int, max_results?: int, proxy_country?: string} $options
     *   - checkin: Check-in date YYYY-MM-DD (with checkout).
     *   - checkout: Check-out date YYYY-MM-DD (with checkin).
     *   - adults: Number of adult guests.
     *   - room_type: Room type filter: entire_home, private_room, hotel_room, shared_room. Omit
     * for all.
     *   - min_price: Minimum nightly price.
     *   - max_price: Maximum nightly price.
     *   - max_results: How many listings to collect across pages. API default: 48.
     *   - proxy_country: Proxy country the request is sent from (ISO-2, e.g. 'US', 'DE'). Defaults
     * to US so prices are in USD.
     * @return array<mixed>
     * Calls POST /travel/airbnb.
     */
    public function airbnbSearch(string $location, array $options = []): array
    {
        return $this->postJson('/travel/airbnb', [
            'location' => $location,
            'checkin' => $options['checkin'] ?? null,
            'checkout' => $options['checkout'] ?? null,
            'adults' => $options['adults'] ?? null,
            'room_type' => $options['room_type'] ?? null,
            'min_price' => $options['min_price'] ?? null,
            'max_price' => $options['max_price'] ?? null,
            'max_results' => $options['max_results'] ?? null,
            'proxy_country' => $options['proxy_country'] ?? null,
        ]);
    }

    /**
     * Scrape an Airbnb listing's full details.
     *
     * Fetches one Airbnb stay (by listing id or room URL) and returns it as JSON: `title`,
     * `description`, `roomType`, `propertyType`, `location` (city, country, `lat`/`lng`), `host`
     * (name, `isSuperhost`, `responseRate`, `yearsHosting`, photo), `rating` (overall plus
     * accuracy, cleanliness, check-in, communication, location, value), `reviewsCount`, `guests`,
     * `bedrooms`, `beds`, `bathrooms`, grouped `amenities`, `photos` with captions, `highlights`,
     * `houseRules`, `checkIn`/`checkOut` times and `isGuestFavorite`. Add `check_in`/`check_out`
     * for `available`, the `cancellationPolicy` and `price` (total, nightly, breakdown) in
     * `currency`; add `include_reviews` for up to `max_reviews` guest `reviews`. Companion to the
     * Airbnb search plugin (`/travel/airbnb`).
     *
     * @param string $room Airbnb listing id (e.g. 23860926) or a room URL on any Airbnb domain,
     * e.g. 'https://www.airbnb.co.uk/rooms/23860926'.
     * @param array{check_in?: string, check_out?: string, adults?: int, children?: int, infants?: int, pets?: int, currency?: string, locale?: string, include_reviews?: bool, max_reviews?: int, reviews_sort?: string, proxy_country?: string} $options
     *   - check_in: Check-in date YYYY-MM-DD. With check_out, adds price, availability and the
     * cancellation policy.
     *   - check_out: Check-out date YYYY-MM-DD (with check_in).
     *   - adults: Adult guests (affects the price). API default: 1.
     *   - children: Children aged 2-12. API default: 0.
     *   - infants: Infants under 2. API default: 0.
     *   - pets: Pets. API default: 0.
     *   - currency: Price currency, ISO code such as USD, EUR, GBP. API default: USD.
     *   - locale: Language for Airbnb's texts, e.g. en, de, fr, es, pt-BR. Host-written text is
     * returned translated when Airbnb has a translation. API default: en.
     *   - include_reviews: Also return guest reviews. API default: false.
     *   - max_reviews: How many reviews to return with include_reviews (1-100). API default: 20.
     *   - reviews_sort: Review order: most_relevant, most_recent, highest_rated, lowest_rated. API
     * default: most_relevant.
     *   - proxy_country: Proxy country the request is sent from (ISO-2, e.g. 'US', 'DE'). Defaults
     * to US.
     * @return array<mixed>
     * Calls POST /travel/airbnb-room.
     */
    public function airbnbRoom(string $room, array $options = []): array
    {
        return $this->postJson('/travel/airbnb-room', [
            'room' => $room,
            'check_in' => $options['check_in'] ?? null,
            'check_out' => $options['check_out'] ?? null,
            'adults' => $options['adults'] ?? null,
            'children' => $options['children'] ?? null,
            'infants' => $options['infants'] ?? null,
            'pets' => $options['pets'] ?? null,
            'currency' => $options['currency'] ?? null,
            'locale' => $options['locale'] ?? null,
            'include_reviews' => $options['include_reviews'] ?? null,
            'max_reviews' => $options['max_reviews'] ?? null,
            'reviews_sort' => $options['reviews_sort'] ?? null,
            'proxy_country' => $options['proxy_country'] ?? null,
        ]);
    }

    /**
     * Scrape all reviews of an Airbnb listing.
     *
     * Given an Airbnb `room` (listing id or room URL), returns its guest `reviews`: `id`,
     * `rating`, `text` (as written) with its `language`, `translatedText` (Airbnb's translation
     * into `locale`), `date` (ISO), `localizedDate`, `stayDetail`, `photos`, `reviewer` (`id`,
     * `name`, `photo`, `location` or `tenure`, `profileUrl`, `profileId`, `isSuperhost`,
     * `deleted`) and the host's `response`. `reviewer.id` is Airbnb's account id (the one in its
     * photo URLs; airbnb.com/users/show/<id> asks anonymous visitors to log in), while
     * `profileUrl` is the public profile link Airbnb's own review cards open, keyed by a separate
     * public id given as `profileId`. `deleted` is true when the guest has since closed their
     * Airbnb account; Airbnb still sends the name, photo and location or tenure from the review,
     * and they are returned as sent. Reads every review, not just the few on the room page: page
     * with `page` (or `offset`) and `max_reviews` (up to 500 per call), order with `sort`
     * (most_relevant, most_recent, highest_rated, lowest_rated) and drop older reviews with
     * `since`. Also returns the `listing` summary (title, overall and category `rating`,
     * `ratingDistribution`, `ratingCounts`, `reviewsCount`, `reviewTags`, host) and
     * `totalResults`, `hasMore`, `nextPage`, `nextOffset`. `ratingDistribution` is Airbnb's own
     * list of each star's share of the ratings as a 0-1 fraction (`{"stars": 5, "percentage":
     * 0.957}` = 95.7%), not a count like the other review plugins return; `ratingCounts` gives the
     * number of ratings per star (`{"5": 692, ...}`) worked out from those shares and
     * `reviewsCount`, and is null when the shares do not fit it (seen on hotel listings, whose
     * distribution covers more ratings than `reviewsCount`). Billed one unit per 50-review page
     * read (`pagesFetched`). Companion to the Airbnb search (`/travel/airbnb`) and listing
     * (`/travel/airbnb-room`) plugins.
     *
     * @param string $room Airbnb listing id (e.g. 23860926) or a room URL on any Airbnb domain,
     * e.g. 'https://www.airbnb.co.uk/rooms/23860926'.
     * @param array{max_reviews?: int, page?: int, offset?: int, sort?: string, locale?: string, since?: string, include_listing?: bool, proxy_country?: string} $options
     *   - max_reviews: How many reviews to return (1-500). Airbnb serves 50 reviews per request;
     * each request is one billed unit. API default: 50.
     *   - page: 1-based page of `max_reviews`-sized pages (1-1000). Use the `nextPage` of a
     * previous response to continue. API default: 1.
     *   - offset: Start at this review position instead of `page` (0-20000). Use the `nextOffset`
     * of a previous response to resume exactly.
     *   - sort: Review order: most_relevant, most_recent, highest_rated, lowest_rated (the default
     * is Airbnb's own order). API default: most_relevant.
     *   - locale: Language to translate reviews and host responses into, e.g. en, de, fr, es, pt-
     * BR. The original text and its language are always returned too. API default: en.
     *   - since: Only reviews written on or after this date (YYYY-MM-DD). With sort=most_recent it
     * also stops paging once older reviews start.
     *   - include_listing: Also return the listing summary (title, overall and category ratings,
     * rating distribution, host). Set false to skip that request. API default: true.
     *   - proxy_country: Proxy country the request is sent from (ISO-2, e.g. 'US', 'DE').
     * @return array<mixed>
     * Calls POST /travel/airbnb-reviews.
     */
    public function airbnbReviews(string $room, array $options = []): array
    {
        return $this->postJson('/travel/airbnb-reviews', [
            'room' => $room,
            'max_reviews' => $options['max_reviews'] ?? null,
            'page' => $options['page'] ?? null,
            'offset' => $options['offset'] ?? null,
            'sort' => $options['sort'] ?? null,
            'locale' => $options['locale'] ?? null,
            'since' => $options['since'] ?? null,
            'include_listing' => $options['include_listing'] ?? null,
            'proxy_country' => $options['proxy_country'] ?? null,
        ]);
    }

    /**
     * Scrape a TripAdvisor list (restaurants / hotels / attractions).
     *
     * Given a TripAdvisor list `url` (Restaurants, Hotels or Attractions for a city/area), returns
     * the places as JSON: `name`, `url`, `image`, `rating`, `reviewCount`, `priceRange`,
     * `cuisine`, `phone`, `address`, `country` and `coordinates`. Paginates through TripAdvisor's
     * `-oaN-` pages up to `max_results`. Data is read from TripAdvisor's schema.org ld+json, which
     * is more stable than its HTML.
     *
     * @param string $url TripAdvisor list URL (Restaurants / Hotels / Attractions), e.g.
     * https://www.tripadvisor.com/Restaurants-g60763-New_York_City_New_York.html
     * @param array{max_results?: int, page?: int, proxy_country?: string} $options
     *   - max_results: How many places to collect across pages (~30 per page, max 1020).
     * TripAdvisor renders slowly, so large values take a while. API default: 30.
     *   - page: 1-based results page to start from. API default: 1.
     *   - proxy_country: Proxy country the request is sent from (ISO-2, e.g. 'US', 'DE'). Leave
     * blank to let the API pick.
     * @return array<mixed>
     * Calls POST /travel/tripadvisor.
     */
    public function tripadvisorList(string $url, array $options = []): array
    {
        return $this->postJson('/travel/tripadvisor', [
            'url' => $url,
            'max_results' => $options['max_results'] ?? null,
            'page' => $options['page'] ?? null,
            'proxy_country' => $options['proxy_country'] ?? null,
        ]);
    }

    /**
     * Scrape TripAdvisor reviews (hotels / restaurants / attractions).
     *
     * Given a TripAdvisor place review `url` (Hotel_Review, Restaurant_Review, Attraction_Review
     * or AttractionProductReview, any TripAdvisor site) or a `location_id`, returns the place
     * summary (`name`, `type`, `rating`, `reviewsCount`, `ratingHistogram`, `subratings`,
     * `address`, `coordinates`, `phone`, `website`) and its `reviews`: `title`, `text`, `rating`,
     * `publishedDate`, `travelDate`, `tripType`, `language`, `helpfulVotes`, `user`, `subratings`,
     * `photos` and `ownerResponse`. Newest first; pages through TripAdvisor's review pages up to
     * `max_reviews`. Pick the review language with `language` and cut off old reviews with
     * `since`. Billed one unit per review page fetched (`pagesFetched`).
     *
     * @param string|null $url TripAdvisor place review page on any TripAdvisor site: Hotel_Review,
     * Restaurant_Review, Attraction_Review or AttractionProductReview, e.g.
     * https://www.tripadvisor.com/Hotel_Review-g60763-d93589-Reviews-The_Michelangelo_New_York-
     * New_York_City_New_York.html. Pass this or `location_id`.
     * @param array{location_id?: int, max_reviews?: int, page?: int, language?: string, since?: string, proxy_country?: string} $options
     *   - location_id: TripAdvisor location id (the digits after -d in a place URL, e.g. 93589).
     * Pass this or `url`.
     *   - max_reviews: How many reviews to collect across pages (1-200). TripAdvisor shows 10
     * reviews per page (15 for restaurants); each page is one billed unit. API default: 20.
     *   - page: 1-based review page to start from (10 reviews per page, 15 for restaurants). Use
     * the `nextPage` of a previous response to continue. API default: 1.
     *   - language: Review language, which TripAdvisor ties to its site: en, de, fr, it, es, pt,
     * nl, ja, ko, ru, sv, tr, da. Default: the language of the URL's site (tripadvisor.com = en),
     * or - when that site lists no reviews for the place - the place's most-reviewed of these
     * languages. Reviews written in other languages appear machine-translated, flagged by
     * `isMachineTranslated` and `originalLanguage`.
     *   - since: Only reviews published on or after this date (YYYY-MM-DD). Stops paging once
     * older reviews start, so it also saves pages.
     *   - proxy_country: Proxy country the request is sent from (ISO-2, e.g. 'US', 'DE'). Leave
     * blank: pinning a country makes the call much slower.
     * @return array<mixed>
     * Calls POST /travel/tripadvisor-reviews.
     */
    public function tripadvisorReviews(?string $url = null, array $options = []): array
    {
        return $this->postJson('/travel/tripadvisor-reviews', [
            'url' => $url,
            'location_id' => $options['location_id'] ?? null,
            'max_reviews' => $options['max_reviews'] ?? null,
            'page' => $options['page'] ?? null,
            'language' => $options['language'] ?? null,
            'since' => $options['since'] ?? null,
            'proxy_country' => $options['proxy_country'] ?? null,
        ]);
    }

    /**
     * Scrape Google Shopping product listings.
     *
     * Runs the Google Shopping vertical (`udm=28`) for `q` and returns the product cards as JSON:
     * `title`, `price`, `currency`, `currencyCode`, `originalPrice`, `discount`, `merchant`,
     * `rating`, `reviewCount` and Google's own ids for the product (`productId`, `catalogId`,
     * `offerId` - stable across searches, for tracking one product). Set `proxy_country`/`gl` to
     * target a market (prices/merchants are region-specific) and `min_price`/`max_price` to
     * filter. One render returns the first page of products (v1). Note: Google Shopping exposes no
     * per-product URL, so `url` is omitted and `image` is best-effort.
     *
     * @param string $q Product search term, e.g. 'wireless headphones'.
     * @param array{gl?: string, min_price?: int, max_price?: int, max_results?: int, proxy_country?: string} $options
     *   - gl: Market of search, ISO-2, e.g. 'us', 'de'. Sets prices/merchants. API default: us.
     *   - min_price: Minimum price filter (whole units, gl currency).
     *   - max_price: Maximum price filter (whole units, gl currency).
     *   - max_results: How many products to return (v1: first page). API default: 60.
     *   - proxy_country: Proxy country the request is sent from (ISO-2, e.g. 'US', 'DE').
     * Prices/merchants are market-specific.
     * @return array<mixed>
     * Calls POST /goods/google-shopping.
     */
    public function googleShopping(string $q, array $options = []): array
    {
        return $this->postJson('/goods/google-shopping', [
            'q' => $q,
            'gl' => $options['gl'] ?? null,
            'min_price' => $options['min_price'] ?? null,
            'max_price' => $options['max_price'] ?? null,
            'max_results' => $options['max_results'] ?? null,
            'proxy_country' => $options['proxy_country'] ?? null,
        ]);
    }

    /**
     * Scrape Google Jobs listings.
     *
     * Runs the Google Jobs vertical (`udm=8`) for `q` and returns the job cards as JSON: `title`,
     * `company`, `location`, `via` (source), `salary`, `employmentType`, `remote`, `postedAge`,
     * `qualifications`, `benefits`, `logo`, a stable `jobId` and a `shareUrl`. Append a `location`
     * to narrow the search, and set `proxy_country`/`gl`/`hl` to target a market. One render
     * returns ~10 jobs (v1).
     *
     * @param string $q Job search term, e.g. 'software engineer' or 'nurse'.
     * @param array{location?: string, hl?: string, gl?: string, max_results?: int, proxy_country?: string} $options
     *   - location: Optional location, appended to the query, e.g. 'Austin, TX'.
     *   - hl: Google UI language, e.g. 'en', 'de'. API default: en.
     *   - gl: Google country of search, ISO-2, e.g. 'us'. API default: us.
     *   - max_results: How many jobs to return. One render yields ~10 (v1). API default: 10.
     *   - proxy_country: Proxy country the request is sent from (ISO-2, e.g. 'US', 'DE'). Jobs are
     * location-sensitive; pick the market you want.
     * @return array<mixed>
     * Calls POST /jobs/google-jobs.
     */
    public function googleJobs(string $q, array $options = []): array
    {
        return $this->postJson('/jobs/google-jobs', [
            'q' => $q,
            'location' => $options['location'] ?? null,
            'hl' => $options['hl'] ?? null,
            'gl' => $options['gl'] ?? null,
            'max_results' => $options['max_results'] ?? null,
            'proxy_country' => $options['proxy_country'] ?? null,
        ]);
    }

    /**
     * Scrape Google Trends (interest over time, by region, related queries).
     *
     * Compares 1-5 `keywords` on Google Trends and returns the data behind the explore page as
     * JSON: `interestOverTime` (one point per time bucket with a 0-100 value per keyword, ISO
     * `date`, `timestamp`, `isPartial`), `averages`, `interestByRegion` (`geoCode`, `geoName`,
     * values per keyword), and per keyword `relatedQueries` and `relatedTopics` (opt-in via
     * `sections`), each with `top` and `rising` lists. Filter with `geo` (worldwide, country,
     * region or US metro), `timeframe` (presets such as 'today 12-m' or a custom date range),
     * `category` and `property` (web, images, news, youtube, shopping). Use `sections` to fetch
     * only what you need. Billed as one request per keyword compared.
     *
     * @param string|string[] $keywords 1-5 search terms to compare, comma-separated, e.g.
     * 'coffee,tea'. A Knowledge Graph topic id such as '/m/0dl567' also works.
     * @param array{geo?: string, timeframe?: string, category?: int, property?: string, hl?: string, tz?: int, region_resolution?: string, include_low_volume?: bool, sections?: string, proxy_country?: string} $options
     *   - geo: Where: empty = worldwide, an ISO-2 country ('US'), a region ('US-CA') or a US metro
     * ('US-CA-807').
     *   - timeframe: Time range: now 1-H, now 4-H, now 1-d, now 7-d, today 1-m, today 3-m, today
     * 12-m, today 5-y, all, or a custom 'YYYY-MM-DD YYYY-MM-DD' (hourly for the last 7 days:
     * 'YYYY-MM-DDTHH YYYY-MM-DDTHH'). API default: today 12-m.
     *   - category: Google Trends category id (0 = all categories, e.g. 71 = Food & Drink, 5 =
     * Computers & Electronics). API default: 0.
     *   - property: Which Google search to measure: web, images, news, youtube, shopping. API
     * default: web.
     *   - hl: Language of labels (region names, topic titles), e.g. 'en-US', 'de', 'fr'. API
     * default: en-US.
     *   - tz: Timezone offset in minutes that day/hour buckets align to (Trends' convention: 300 =
     * UTC-5, -60 = UTC+1). Default 0 = UTC. API default: 0.
     *   - region_resolution: Level of the interest-by-region map: country, region, city, dma.
     * Default = Trends' own choice (countries worldwide, regions in a country).
     *   - include_low_volume: Include regions with low search volume in the region map. API
     * default: false.
     *   - sections: What to fetch: a comma list of interest_over_time, interest_by_region,
     * related_queries, related_topics, or 'all'. Fewer sections = faster. related_topics is opt-in
     * (Google often returns it empty). API default:
     * interest_over_time,interest_by_region,related_queries.
     *   - proxy_country: Proxy country the request is sent from (ISO-2, e.g. 'US', 'DE'). Optional
     * - by default a country outside the US and Europe is used; results follow `geo`, not the
     * proxy country.
     * @return array<mixed>
     * Calls POST /trends/google-trends.
     */
    public function googleTrends(string|array $keywords, array $options = []): array
    {
        return $this->postJson('/trends/google-trends', [
            'keywords' => self::pluginJoin($keywords, ","),
            'geo' => $options['geo'] ?? null,
            'timeframe' => $options['timeframe'] ?? null,
            'category' => $options['category'] ?? null,
            'property' => $options['property'] ?? null,
            'hl' => $options['hl'] ?? null,
            'tz' => $options['tz'] ?? null,
            'region_resolution' => $options['region_resolution'] ?? null,
            'include_low_volume' => $options['include_low_volume'] ?? null,
            'sections' => $options['sections'] ?? null,
            'proxy_country' => $options['proxy_country'] ?? null,
        ]);
    }

    /**
     * Scrape Google Maps place details.
     *
     * Returns the full data for one Google Maps place as JSON: `name`, `address` (+
     * `addressLines`), `phone`, `website`, `rating`, `categories`, `latitude`/`longitude`,
     * `plusCode`, `hours` + `openNow`, `description`, `photo`, `cid`, `featureId`, `googleMapsUrl`
     * and `relatedPlaces`. Identify the place with `place_id` (ChIJ...), a Maps `url`, or a raw
     * `feature_id` (0xHEX:0xHEX). Location-neutral - the feature id resolves the place directly;
     * `proxy_country` defaults to a US proxy to clear Google's consent wall.
     *
     * @param array{url?: string, place_id?: string, feature_id?: string, hl?: string, gl?: string, proxy_country?: string, raw?: bool} $options
     *   - url: A Google Maps place URL (share link or /maps/place/... URL). The feature id or
     * place_id is read out of it.
     *   - place_id: A Google place_id, e.g. 'ChIJN1t_tDeuEmsRUsoyG83frY4'.
     *   - feature_id: A Maps feature id '0xHEX:0xHEX', e.g.
     * '0x47e66e2964e34e2d:0x8ddca9ee380ef7e0'. Fastest - no resolve step.
     *   - hl: Google UI language, e.g. 'en', 'de', 'fr'. API default: en.
     *   - gl: Google country, ISO-2 lowercase, e.g. 'us'. API default: us.
     *   - proxy_country: Proxy country the request is sent from (ISO-2, e.g. 'US', 'DE'). Defaults
     * to US - an EU country hits Google's consent wall. API default: us.
     *   - raw: Include the decoded place core array under `raw`. API default: false.
     * @return array<mixed>
     * Calls POST /maps/place-details.
     */
    public function mapsPlaceDetails(array $options = []): array
    {
        return $this->postJson('/maps/place-details', [
            'url' => $options['url'] ?? null,
            'place_id' => $options['place_id'] ?? null,
            'feature_id' => $options['feature_id'] ?? null,
            'hl' => $options['hl'] ?? null,
            'gl' => $options['gl'] ?? null,
            'proxy_country' => $options['proxy_country'] ?? null,
            'raw' => $options['raw'] ?? null,
        ]);
    }

    /**
     * Scrape Google Hotels search results (prices, ratings, amenities).
     *
     * Runs a Google Hotels search for `q` and returns the properties as JSON: `name`, `type`
     * (hotel / vacation_rental), `propertyToken`, `price` for the stay (`perNight`,
     * `perNightWithTaxes`, `total`, `totalWithTaxes`, `taxes`, Google's `display` string), `deal`,
     * `rating`, `reviews`, `ratingsBreakdown`, `reviewTopics`, `hotelClass`, `stars`, `amenities`,
     * `description`, `website`, `latitude`/`longitude`, `nearbyPlaces`, `thumbnail`, `images` and
     * `mapsUrl`, plus the page's sponsored `ads`. A query naming one hotel returns just that hotel
     * (`matchedProperty`). Set the stay with `check_in`/`check_out`, the party with `adults` and
     * `children` (ages), and `currency`, `hl` (language) and `gl` (market). `applied` echoes the
     * dates, currency and place Google actually used. Collect up to `max_results` across pages
     * (each Google page is billed as one request, see `pagesFetched`); `nextPageToken` continues
     * the list. Pass a `propertyToken` to `/travel/google-hotels-property` for every booking
