            'stars' => $options['stars'] ?? null,
            'sort' => $options['sort'] ?? null,
            'language' => $options['language'] ?? null,
            'date' => $options['date'] ?? null,
            'search' => $options['search'] ?? null,
            'verified' => $options['verified'] ?? null,
