    /**
     * Scrape Product Hunt launches, products, search and topics.
     *
     * Turns Product Hunt into JSON. `mode=leaderboard` returns a day's ranked launches
     * (`date`=YYYY-MM-DD, or today) with votes, comments, topics and rank; `mode=search` returns
     * products matching `query`; `mode=topic` returns products under a `topic` slug; `mode=detail`
     * returns one product by `slug` with description, website, socials, review rating, followers
     * and categories. Set `max_results` for the list modes.
     *
     * @param array{mode?: string, query?: string, date?: string, topic?: string, slug?: string, max_results?: int, proxy_country?: string} $options
     *   - mode: What to fetch: leaderboard, search, topic, detail. API default: leaderboard.
     *   - query: Search terms (mode=search), e.g. 'ai chatbot'.
     *   - date: Leaderboard day as YYYY-MM-DD (mode=leaderboard). Omit for today. Past days are
     * finalised and ranked; today's board is live and not ranked yet.
     *   - topic: Topic slug (mode=topic), e.g. 'artificial-intelligence'.
     *   - slug: Product slug (mode=detail), e.g. 'notion'.
     *   - max_results: Max products to return for list modes (leaderboard/search/topic). API
     * default: 30.
     *   - proxy_country: Proxy country the request is sent from (ISO-2, e.g. 'US', 'DE'). Leave
     * blank - Product Hunt is global and a forced country only hurts.
     * @return array<mixed>
     * Calls POST /products/producthunt.
     */
    public function productHunt(array $options = []): array
    {
        return $this->postJson('/products/producthunt', [
